def plan(grid_size, starts, goals, obstacles, constraints) -> list:
    from collections import deque
    from heapq import heappop, heappush
    width, height = grid_size
    avoid_agent_collisions = constraints['avoid_agent_collisions']
    max_steps = constraints['max_steps']
    movement = constraints['movement']
    obstacles_set = set(obstacles)

    def is_valid(pos):
        x, y = pos
        return 0 <= x < width and 0 <= y < height and (pos not in obstacles_set)

    def get_neighbors(pos):
        x, y = pos
        neighbors = []
        for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx, ny = (x + dx, y + dy)
            if is_valid((nx, ny)):
                neighbors.append((nx, ny))
        return neighbors

    def bfs(start, goal):
        queue = deque([(start, 0, [])])
        visited = set([start])
        path = {start: ([], 0)}
        while queue:
            pos, steps, path_history = queue.popleft()
            if pos == goal:
                return path_history + [pos]
            for neighbor in get_neighbors(pos):
                if neighbor not in visited:
                    visited.add(neighbor)
                    new_path_history = path_history + [pos]
                    if avoid_agent_collisions:
                        valid = True
                        for step in new_path_history:
                            if new_path_history.count(step) > 1:
                                valid = False
                                break
                        if valid:
                            path[neighbor] = (new_path_history, steps + 1)
                            queue.append((neighbor, steps + 1, new_path_history))
        return None
    paths = []
    for start, goal in zip(starts, goals):
        path = bfs(start, goal)
        if path:
            paths.append(path)
        else:
            return []
    return paths
